  '<div class="book-page"><div class="page-break" data-chapter="25" data-page-id="page_260"></div><p class="class_s2d" data-chapter="25" id="page_260">The Clocks</p>\n<p class="class_s2d">Third Girl</p>\n<p class="class_s2d">Hallowe\u2019en Party</p>\n<p class="class_s2d">Elephants Can Remember</p>\n<p class="class_s2d">Curtain: Poirot\u2019s Last Case</p>\n<p class="class_s4">The Miss Marple Mysteries</p>\n<p class="class_s2d">The Murder at the Vicarage</p>\n<p class="class_s2d">The Body in the Library</p>\n<p class="class_s2d">The Moving Finger</p>\n<p class="class_s2d">A Murder Is Announced</p>\n<p class="class_s2d">They Do It with Mirrors</p>\n<p class="class_s2d">A Pocket Full of Rye</p>\n<p class="class_s2d">4:50 from Paddington</p>\n<p class="class_s2d">The Mirror Crack\u2019d</p>\n<p class="class_s2d">A Caribbean Mystery</p>\n<p class="class_s2d">At Bertram\u2019s Hotel</p>\n<p class="class_s2d">Nemesis</p>\n<p class="class_s2d">Sleeping Murder</p>\n<p class="class_s2d">Miss Marple: The Complete Short Story Collection</p>\n<p class="class_s4">The Tommy and Tuppence Mysteries</p>\n<p class="class_s2d">The Secret Adversary</p>\n<p class="class_s2d">Partners in Crime</p>\n<p class="class_s2d">N or M?</p>\n<p class="class_s2d">By the Pricking of My Thumbs</p>\n<p class="class_s2d">Postern of Fate</p>\n<p class="class_s4">Memoir</p>\n<p class="class_s2d">An Autobiography</p>\n<div class="book-page"></div>',
